#!/usr/bin/env python3
# tools/titan/results/wave55-plan/geometry-gate.py — PLAN.md §6 R6 / revert rule 4 as one executable read-out (wave 55).
#
# The wave-54 runner (tools/titan/results/wave54-plan/geometry-gate.py) with three changes, each a wave-55 plan decision:
#   1. --sections a,b (briefs-audit C15). Every expect key now carries the cell it reads (`keyCells`, generated by
#      plan-build.py), so a key whose section is not in the list prints NOT PROBED and gates nothing — a stage-1 read-out
#      of 9 sections no longer reports the other sections' gating keys UNMEASURED (exit 3), and a probe none of whose
#      keys is in the list is not even run. A key of a LISTED section that cannot be read is still UNMEASURED (exit 3).
#   2. The script token is the first `*.py` token of the cmd (the cmd starts with the pinned interpreter `PY -B`,
#      C14), and a cmd that does not start with expectations.json `interpreter` is refused (exit 2) — a probe run under
#      another python is not the probe the plan registered.
#   3. The defaults are wave 55's (base wave55-open, the wave55-plan expectations); every key class, exit code and the
#      --self-test contract are wave 54's.
#   4. Plan-skeptic round 1 (instrument-teeth S2): a scope that matches NOTHING is refused (exit 2), never a vacuous pass —
#      a --sections entry that is neither a keyCells section nor a section directory of the run, a --lanes entry that is a
#      prefix of no lane, or 0 keys in scope; usage errors exit 2 (exit 1 means "a gating key FAILed" and nothing else).
#   5. Plan-skeptic round 2 (instrument-teeth S2 / S5): a flag given without its value, and an EMPTY --lanes / --sections
#      entry (`--lanes L1,` — the empty string is a prefix of every lane and silently widened the read to all 43 keys), are
#      usage errors (exit 2), never an IndexError (exit 1 reads "a gating key FAILed"); --base equal to the run is refused
#      (exit 2: every base-relative read — L1 glyph identity, L6 [X], the L3 / L5 [C] / [K] controls, L4 `crop:` — compares
#      the picture with itself and passes vacuously), except under --self-test, whose contract is the pre-fix identity pair;
#      a --base run with no sections/ directory is refused (exit 2) instead of reading as UNMEASURED (exit 3).
# Per expect key, one verdict:
#   PASS        the probe line for that key ends in the exact expected string (and contains its `contains` string);
#   FAIL        it does not;
#   UNMEASURED  the capture is MISSING or no line names the key — never a pass, never a fail;
#   NOT PROBED  (--sections only) the key's section is not in the list: printed, never counted.
# and one CLASS per key: GATING (a FAIL reverts the unit it names), WITHDRAWN (a probe decision reverted a unit it
# needs), control (expected to PASS and keep passing; a FAIL is loud, diagnosed through rule 5 / R4, never exit 1),
# report (a target expected WRONG today: read and labelled). A probe that exits non-zero failed its OWN ref self-check:
# the RULE is wrong, not the lane — SELF-CHECK FAILED, exit 1.
#
# Usage: /opt/homebrew/bin/python3.12 -B tools/titan/results/wave55-plan/geometry-gate.py <run> [--base wave55-open]
#        [--lanes L1,L4] [--sections css-text,selectors] [--json out.json] [--exp expectations.json] [--self-test]
#   exit 1 on a GATING FAIL or a probe self-check failure; 2 on a usage error, an empty / unknown scope (--sections,
#   --lanes, 0 keys), when expectations.json is STALE (a gating key needs a unit
#   probeDecisions lists as reverted) or a cmd is off the pinned interpreter; 3 when no gating key FAILs but a GATING key
#   of a probed section is UNMEASURED. --self-test (on the pre-fix run, e.g. wave54-final --base wave54-final): exit 0
#   iff every GATING key FAILs, every control PASSes and every report key FAILs (keys NOT PROBED are left out).
import json, os, re, subprocess, sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, '..', '..', '..', '..'))
args = sys.argv[1:]
USAGE = 'usage: geometry-gate.py <run> [--base wave55-open] [--lanes L1,L4] [--sections a,b] [--json out.json] [--exp file] [--self-test]'
def opt(name, default=None):
    """Pop `--name value` from args (the run id is the one positional argument left); a flag without a value is a usage
    error, exit 2 (round 2, S5)."""
    if name in args:
        i = args.index(name)
        if i + 1 >= len(args) or args[i + 1].startswith('--'):
            print(f'{USAGE}\n  REFUSED — {name} given without a value', file=sys.stderr); sys.exit(2)
        val = args[i + 1]; del args[i:i + 2]; return val
    return default
def flag(name):
    """Pop a bare `--name` switch."""
    if name in args:
        args.remove(name); return True
    return False
base = opt('--base', 'wave55-open')
only = opt('--lanes')
sections_opt = opt('--sections')
json_out = opt('--json')
exp_path = opt('--exp', os.path.join(HERE, 'expectations.json'))   # a dry-run expectations.json (plan-build.py --out)
self_test = flag('--self-test')
if len(args) != 1:
    print(USAGE, file=sys.stderr)
    sys.exit(2)
run = args[0]
# Round 2 (S2): a base equal to the run makes every base-relative read vacuous; a base with no captures is not a base.
if base == run and not self_test:
    print(f'REFUSED — --base {base} is the run itself: every base-relative read (L1 glyphs, L6 [X], L3 / L5 [C] / [K], L4 crop) would compare '
          'the picture with itself and pass; read against the opening run (wave55-open) — only --self-test reads the pre-fix identity pair')
    sys.exit(2)
if not os.path.isdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'runs', base, 'sections')):
    print(f'REFUSED — --base {base} has no sections/ directory under tools/titan/runs: no base capture can be read')
    sys.exit(2)
EXP = json.load(open(exp_path))
SECTIONS = set(sections_opt.split(',')) if sections_opt else None
# Round 1 (S2): an empty or unknown scope is a refusal, never "0 keys — PASS 0".
_key_secs = {c.split('/')[0] for l in EXP['lanes'].values() for pr in l.get('geometryProbes', []) for c in pr.get('keyCells', {}).values()}
_run_dir = os.path.join(ROOT, 'tools', 'titan', 'runs', run, 'sections')
_run_secs = set(os.listdir(_run_dir)) if os.path.isdir(_run_dir) else set()
_bad_secs = sorted(x for x in (SECTIONS or ()) if x not in _key_secs and x not in _run_secs)
_bad_lanes = [x for x in (only.split(',') if only else []) if not x.strip() or not any(l.startswith(x) for l in EXP['lanes'])]
_bad_secs += ['(empty entry)'] if sections_opt is not None and any(not x.strip() for x in sections_opt.split(',')) else []   # round 2 (S5)
if _bad_secs or _bad_lanes or (only is not None and not only.strip()) or (sections_opt is not None and not sections_opt.strip()):
    print(f'REFUSED — unknown scope: --sections {_bad_secs or "-"} (neither a key\'s section nor a section of {run}); --lanes {_bad_lanes or "-"} '
          f'(a prefix of no lane in {sorted(EXP["lanes"])}): an empty scope would read as a vacuous pass')
    sys.exit(2)
norm = lambda s: re.sub(r'\s+', ' ', s.strip())       # probes pad their columns with runs of spaces
script_of = lambda cmd: os.path.basename(next(t for t in cmd.split() if t.endswith('.py')))
section_of_key = lambda probe, key: probe['keyCells'][key].split('/')[0]

# STALE guard (wave-54 fix r1, M3): a gating key that still needs a unit probeDecisions lists as reverted means the JSON
# was not regenerated — refuse rather than name a unit that is gone.
reverted = {(d['lane'], d['unit']) for d in ((EXP.get('probeDecisions') or {}).get('reverted') or [])}
stale, off_interp = [], []
for lane_id, lane in EXP['lanes'].items():
    for probe in lane.get('geometryProbes', []):
        if not probe['cmd'].startswith(EXP['interpreter'] + ' '):
            off_interp.append(f'{lane_id} {probe["cmd"]}')
        missing = set(probe['expect']) - set(probe.get('keyCells', {}))
        if missing:
            off_interp.append(f'{lane_id} {script_of(probe["cmd"])}: keys without keyCells {sorted(missing)[:3]}')
        for key, spec in probe.get('gating', {}).items():
            needs = set(probe.get('requires', {}).get(key) or spec.split('|'))
            stale += [f'{lane_id} {key} needs {u}' for u in needs if (lane_id, u) in reverted]
if stale:
    print('STALE expectations.json — gating keys of reverted units (re-run plan-build.py):\n  ' + '\n  '.join(stale))
    sys.exit(2)
if off_interp:
    print(f'REFUSED — probe cmds off the pinned interpreter `{EXP["interpreter"]}` or keys without a section (C14 / C15):\n  ' + '\n  '.join(off_interp))
    sys.exit(2)

def find_line(lines, key):
    """The probe line naming `key`: its tokens appear contiguously within the first len(key)+2 tokens of the line
    (some probes prefix a run id; every wave-55 probe starts with the key)."""
    kt = key.split()
    hits = []
    for l in lines:
        t = l.split()
        for i in range(0, min(3, max(0, len(t) - len(kt) + 1))):
            if t[i:i + len(kt)] == kt:
                hits.append(l); break
    return hits

report, gating_fail, selfcheck_fail, not_probed = [], 0, 0, 0
for lane_id, lane in EXP['lanes'].items():
    if only and not any(lane_id.startswith(x) for x in only.split(',')):
        continue
    for probe in lane.get('geometryProbes', []):
        cmd = probe['cmd'].replace('<run>', run).replace('<base>', base)
        script = script_of(cmd)
        keys = list(probe['expect'])
        in_scope = [k for k in keys if SECTIONS is None or section_of_key(probe, k) in SECTIONS]
        for k in keys:
            if k not in in_scope:
                not_probed += 1
                print(f'   {lane_id:24} {script:42} {k:58} NOT PROBED [section {section_of_key(probe, k)} not in --sections]')
        if not in_scope:
            continue                                   # nothing of this probe is in the probed sections: not run
        proc = subprocess.run(['nice', '-n', '19'] + cmd.split(), cwd=ROOT, capture_output=True, text=True)
        lines = [norm(l) for l in proc.stdout.splitlines() if l.strip()]
        if proc.returncode != 0:
            selfcheck_fail += 1
            print(f'!! {lane_id} {script}: exit {proc.returncode} — SELF-CHECK FAILED (the rule, not the lane): {norm(proc.stderr)[-200:]}')
        report_keys = set(probe.get('report', []))
        for key in in_scope:
            want = probe['expect'][key]
            hits = find_line(lines, key)
            gate_unit = probe.get('gating', {}).get(key)
            withdrawn = probe.get('withdrawn', {}).get(key)
            contains = probe.get('contains', {}).get(key, '').replace('<base>', base)
            if not hits or any('MISSING' in h for h in hits):
                verdict, line = 'UNMEASURED', (hits[-1] if hits else '(no line)')
            else:
                line = hits[-1]
                ok = line.endswith(norm(want)) and (not contains or contains in line)
                verdict = 'PASS' if ok else 'FAIL'
            cls = 'gating' if gate_unit else 'withdrawn' if withdrawn else 'report' if key in report_keys else 'control'
            if verdict == 'FAIL' and cls == 'gating':
                gating_fail += 1
            tag = {'gating': f'GATING -> revert {gate_unit}', 'withdrawn': f'WITHDRAWN ({withdrawn})',
                   'report': 'report: expected WRONG until the target is fixed', 'control': 'control: expected to stay PASS'}[cls]
            mark = {'PASS': '  ', 'FAIL': {'gating': '!!', 'control': '!c'}.get(cls, ' -'), 'UNMEASURED': ' ?'}[verdict]
            print(f'{mark} {lane_id:24} {script:42} {key:58} {verdict:10} [{tag}]')
            if verdict != 'PASS':
                print(f'     line: {line[-220:]}')
            report.append({'lane': lane_id, 'script': script, 'key': key, 'cell': probe['keyCells'][key], 'section': section_of_key(probe, key),
                           'verdict': verdict, 'class': cls, 'gatingUnit': gate_unit, 'withdrawn': withdrawn, 'expected': want,
                           'contains': contains or None, 'line': line})

if not report:
    print(f'REFUSED — 0 keys in scope (lanes {only or "all"}, sections {sections_opt or "all"}): nothing was gated, and that is not a pass')
    sys.exit(2)
n = {v: sum(1 for r in report if r['verdict'] == v) for v in ('PASS', 'FAIL', 'UNMEASURED')}
by = lambda c, v: sum(1 for r in report if r['class'] == c and r['verdict'] == v)
scope = f' · sections {sections_opt} (NOT PROBED {not_probed})' if SECTIONS else ''
print(f'\ngeometry-gate {run} (base {base}{scope}): {len(report)} keys — PASS {n["PASS"]} · FAIL {n["FAIL"]} '
      f'(gating {gating_fail}) · UNMEASURED {n["UNMEASURED"]} (gating {by("gating", "UNMEASURED")}) · probe self-check failures {selfcheck_fail}')
print('  by class: ' + ' · '.join(f'{c} {sum(1 for r in report if r["class"] == c)} (PASS {by(c, "PASS")} FAIL {by(c, "FAIL")})'
                                  for c in ('gating', 'control', 'report', 'withdrawn')))
units = sorted({f'{r["lane"]} {r["gatingUnit"]}' for r in report if r['verdict'] == 'FAIL' and r['class'] == 'gating'})
gating_unmeasured = [r for r in report if r['class'] == 'gating' and r['verdict'] == 'UNMEASURED']
if units:
    print('revert rule 4 names:', ', '.join(units))
bad_ctl = [r for r in report if r['class'] == 'control' and r['verdict'] == 'FAIL']
if bad_ctl:
    print(f'CONTROL FAILS ({len(bad_ctl)}) — a must-not-move picture moved; diagnose through rule 5 / R4 (a control on a carrier: the cell review):')
    for r in bad_ctl:
        print(f'   {r["lane"]} {r["script"]} {r["key"]}')
if gating_unmeasured:
    print(f'UNMEASURED GATING KEYS ({len(gating_unmeasured)}) — not a pass: re-run the section (R3); exit 3 unless a gating key FAILed (exit 1):')
    for r in gating_unmeasured:
        print(f'   {r["lane"]} {r["script"]} {r["key"]} [unit {r["gatingUnit"]}]')
if json_out:
    json.dump({'run': run, 'base': base, 'sections': sorted(SECTIONS) if SECTIONS else None, 'rows': report, 'gatingFail': gating_fail,
               'selfCheckFail': selfcheck_fail, 'gatingUnmeasured': len(gating_unmeasured), 'notProbed': not_probed},
              open(json_out, 'w'), indent=1, ensure_ascii=False)
if self_test:
    # The rules can fail (every gating key FAILs on the pre-fix pictures), the controls hold, the report keys are honest.
    viol = [r for r in report if (r['class'] == 'gating' and r['verdict'] != 'FAIL') or (r['class'] == 'control' and r['verdict'] != 'PASS')
            or (r['class'] == 'report' and r['verdict'] != 'FAIL')]
    for r in viol:
        print(f'SELF-TEST VIOLATION {r["class"]} {r["verdict"]}: {r["lane"]} {r["script"]} {r["key"]}')
    print(f'self-test: {"HOLDS" if not viol and not selfcheck_fail else "FAILS"} — {len(viol)} violation(s), {selfcheck_fail} self-check failure(s)')
    sys.exit(0 if not viol and not selfcheck_fail else 1)
sys.exit(1 if gating_fail or selfcheck_fail else 3 if gating_unmeasured else 0)
